-- Existing uncleared adventures receive only missing extras, away from saved players.
do $$
declare saved public.online_adventure_rooms;cfg jsonb;enemies jsonb;mob jsonb;area jsonb;nx int;ny int;
begin
 perform pg_advisory_xact_lock(71390119);
 select data into cfg from public.online_adventure_config where id='floor1';
 for saved in select * from public.online_adventure_rooms where status='active' order by id loop
  perform pg_advisory_xact_lock(hashtextextended('online-room:'||saved.id::text,0));
  select * into saved from public.online_adventure_rooms where id=saved.id for update;
  if coalesce((saved.snapshot->>'stairs')::boolean,false) then continue;end if;
  enemies:=saved.snapshot->'enemies';
  for mob in select value from jsonb_array_elements(cfg->'enemies') where value->>'id' like 'pop_%' loop
   if exists(select 1 from jsonb_array_elements(enemies) e where e->>'id'=mob->>'id') then continue;end if;
   select value into area from jsonb_array_elements(cfg->'areas') where value->>'id'=split_part(mob->>'id','_',2);
   select x,y into nx,ny from generate_series((area->>'x')::int+2,(area->>'x')::int+(area->>'w')::int-3) gx(x)
    cross join generate_series((area->>'y')::int+2,(area->>'y')::int+(area->>'h')::int-3) gy(y)
    where not public.online_adventure_blocked(x,y,1,saved.snapshot)
     and greatest(abs(x-(area->>'sx')::int),abs(y-(area->>'sy')::int))>=3
     and not exists(select 1 from jsonb_array_elements(cfg->'props') prop where greatest(abs(x-(prop->>'x')::int),abs(y-(prop->>'y')::int))<2)
     and not exists(select 1 from jsonb_array_elements(enemies) e where (e->>'hp')::int>0 and greatest(abs(x-(e->>'x')::int),abs(y-(e->>'y')::int))<2)
     and not exists(select 1 from public.online_adventure_members member where member.room_id=saved.id and member.floor=1 and member.finished_at is null and greatest(abs(member.x-gx.x),abs(member.y-gy.y))<5)
     and not exists(select 1 from public.online_adventure_loot loot where loot.room_id=saved.id and loot.floor=1 and loot.x=gx.x and loot.y=gy.y)
    order by abs(x-(mob->>'x')::int)+abs(y-(mob->>'y')::int),y,x limit 1;
   if nx is not null then enemies:=enemies||jsonb_build_array(mob||jsonb_build_object('x',nx,'y',ny,'dir','down','attackBeat',0));end if;
  end loop;
  update public.online_adventure_rooms set snapshot=jsonb_set(saved.snapshot,'{enemies}',enemies) where id=saved.id;
 end loop;
end $$;
commit;
